        index = node.index(desc[0])
        node.insert(index - 1, [field_list])
    else:
        node += field_list

    return field_list


def modify_field_list(
    node: nodes.field_list, annotations: Dict[str, str], suppress_rtype: bool = False
) -> None:
    arguments: Dict[str, Dict[str, bool]] = {}
    param_names = {}  # type: Dict[str, str]  # Maps normalized name to original name
    fields = cast(Iterable[nodes.field], node)
    for field in fields:
        field_name = field[0].astext()
        parts = re.split(" +", field_name)
        if parts[0] == "param":
            if len(parts) == 2:
                # :param xxx:
                name = parts[1]
                normalized_name = name.lstrip("*")
                arg = arguments.setdefault(normalized_name, {})
                arg["param"] = True
                if normalized_name not in param_names:
                    param_names[normalized_name] = name
            elif len(parts) > 2:
                # :param xxx yyy:
                name = " ".join(parts[2:])
                normalized_name = name.lstrip("*")
                arg = arguments.setdefault(normalized_name, {})
                arg["param"] = True
                arg["type"] = True
                if normalized_name not in param_names:
                    param_names[normalized_name] = name
        elif parts[0] == "type":
            name = " ".join(parts[1:])
            normalized_name = name.lstrip("*")
            arg = arguments.setdefault(normalized_name, {})
            arg["type"] = True
            if normalized_name not in param_names:
                param_names[normalized_name] = name
        elif parts[0] == "rtype":
            arguments["return"] = {"type": True}

    for name, annotation in annotations.items():
        if name == "return":
            continue

        arg = arguments.get(name, {})
        # Use the original parameter name from the docstring if available
        param_name = param_names.get(name, name)
        if not arg.get("type"):
            field = nodes.field()
            field += nodes.field_name("", "type " + param_name)
            field += nodes.field_body("", nodes.paragraph("", annotation))
            node += field
        if not arg.get("param"):
            field = nodes.field()
            field += nodes.field_name("", "param " + param_name)
            field += nodes.field_body("", nodes.paragraph("", ""))
            node += field

    if "return" in annotations and "return" not in arguments:
        annotation = annotations["return"]
        if annotation == "None" and suppress_rtype:
            return

        field = nodes.field()
        field += nodes.field_name("", "rtype")
        field += nodes.field_body("", nodes.paragraph("", annotation))
        node += field


def augment_descriptions_with_types(
    node: nodes.field_list, annotations: Dict[str, str], force_rtype: bool
) -> None:
    fields = cast(Iterable[nodes.field], node)
    has_description = set()  # type: Set[str]
    has_type = set()  # type: Set[str]
    param_names = {}  # type: Dict[str, str]  # Maps normalized name to original name
    for field in fields:
        field_name = field[0].astext()
        parts = re.split(" +", field_name)
        if parts[0] == "param":
            if len(parts) == 2:
                # :param xxx:
                name = parts[1]
                normalized_name = name.lstrip("*")
                has_description.add(normalized_name)
                if normalized_name not in param_names:
                    param_names[normalized_name] = name
            elif len(parts) > 2:
                # :param xxx yyy:
                name = " ".join(parts[2:])
                normalized_name = name.lstrip("*")
                has_description.add(normalized_name)
                has_type.add(normalized_name)
                if normalized_name not in param_names:
                    param_names[normalized_name] = name
        elif parts[0] == "type":
            name = " ".join(parts[1:])
            normalized_name = name.lstrip("*")
            has_type.add(normalized_name)
            if normalized_name not in param_names:
                param_names[normalized_name] = name
        elif parts[0] in ("return", "returns"):
            has_description.add("return")
        elif parts[0] == "rtype":
            has_type.add("return")

    # Add 'type' for parameters with a description but no declared type.
    for name in annotations:
        if name in ("return", "returns"):
            continue
        if name in has_description and name not in has_type:
            field = nodes.field()
            # Use the original parameter name from the docstring if available
            param_name = param_names.get(name, name)
            field += nodes.field_name("", "type " + param_name)
            field += nodes.field_body("", nodes.paragraph("", annotations[name]))
            node += field

    # Add 'rtype' if 'return' is present and 'rtype' isn't.
    if "return" in annotations:
        rtype = annotations["return"]
        if "return" not in has_type and (
            "return" in has_description or (force_rtype and rtype != "None")
        ):
            field = nodes.field()
            field += nodes.field_name("", "rtype")
            field += nodes.field_body("", nodes.paragraph("", rtype))
            node += field


def setup(app: Sphinx) -> Dict[str, Any]:
    app.connect("autodoc-process-signature", record_typehints)
    app.connect("object-description-transform", merge_typehints)

    return {
        "version": "builtin",
        "parallel_read_safe": True,
        "parallel_write_safe": True,
    }

